/// The HTML5 named character references (WHATWG), as `name value` pairs
/// separated by `\u{0}`; names include their `;` where the spec has one,
/// and the legacy names without it. Parsed into a map on first use.
library;

Map<String, String>? _map;

/// Name (with its `;` when it has one) → replacement text.
Map<String, String> get entities => _map ??= _parse();

/// The longest name, for the longest-match scan.
const longestEntity = 32;

Map<String, String> _parse() {
  final out = <String, String>{};
  final parts = _table.split('\u{0}');
  for (var i = 0; i + 1 < parts.length; i += 2) {
    out[parts[i]] = parts[i + 1];
  }
  return out;
}

